import streamlit as st
import base64

st.set_page_config(
    page_title="태양계 몸무게 계산기",
    page_icon="🪐",
    layout="centered"
)

st.markdown("""
<style>
.큰제목 {
    font-size: 42px;
    font-weight: bold;
    text-align: center;
    margin-bottom: 20px;
}
.설명 {
    font-size: 22px;
    text-align: center;
    line-height: 1.8;
    margin-bottom: 30px;
}
.천체이름 {
    font-size: 30px;
    font-weight: bold;
    text-align: center;
    margin: 15px 0;
}
.stSelectbox label {
    font-size: 24px !important;
    font-weight: bold !important;
}
.stSelectbox div {
    font-size: 22px !important;
}
.stNumberInput label {
    font-size: 24px !important;
    font-weight: bold !important;
}
.stNumberInput input {
    font-size: 24px !important;
    padding: 15px !important;
}
.stButton button {
    font-size: 26px !important;
    font-weight: bold !important;
    padding: 15px !important;
    width: 100%;
}
.결과제목 {
    font-size: 28px;
    font-weight: bold;
    text-align: center;
    margin-top: 35px;
}
.결과숫자 {
    font-size: 64px;
    font-weight: bold;
    text-align: center;
    margin: 15px 0 25px 0;
}
.안내 {
    font-size: 25px;
    font-weight: bold;
    text-align: center;
    line-height: 1.8;
    margin-top: 30px;
}
.설명2 {
    font-size: 20px;
    text-align: center;
    line-height: 1.8;
}
.이미지설명 {
    font-size: 18px;
    text-align: center;
    margin-bottom: 25px;
}
</style>
""", unsafe_allow_html=True)

st.markdown(
    '<div class="큰제목">🪐 태양계 몸무게 계산기</div>',
    unsafe_allow_html=True
)

st.markdown(
    '<div class="설명">천체를 선택하면 그 천체의 모습을 볼 수 있습니다.<br>내 몸무게가 얼마가 되는지도 계산해 보세요.</div>',
    unsafe_allow_html=True
)

천체중력 = {'태양': 27.01, '수성': 0.378, '금성': 0.907, '지구': 1.0, '달': 0.165, '화성': 0.377, '목성': 2.36, '토성': 0.916, '천왕성': 0.889, '해왕성': 1.12}

선택목록 = ['태양', '달', '수성', '금성', '화성', '목성', '토성', '천왕성', '해왕성']

천체이미지 = {
    "태양": "",
    "달": "",
    "수성": "",
    "금성": "",
    "화성": "",
    "목성": "",
    "토성": "",
    "천왕성": "",
    "해왕성": "",
}

선택한천체 = st.selectbox(
    "태양계 천체 선택",
    선택목록
)

이미지바이트 = base64.b64decode(천체이미지[선택한천체])

st.image(
    이미지바이트,
    use_container_width=True
)

st.markdown(
    '<div class="천체이름">' + 선택한천체 + '</div>',
    unsafe_allow_html=True
)

st.markdown(
    '<div class="이미지설명">선택한 천체의 모습을 참고한 이미지입니다.</div>',
    unsafe_allow_html=True
)

몸무게 = st.number_input(
    "나의 몸무게",
    min_value=0.0,
    value=0.0,
    step=0.1,
    format="%.1f"
)

if st.button("계산하기"):

    if 몸무게 == 0:

        st.markdown(
            '<div class="안내">몸무게를 1kg 이상 입력해 주세요.</div>',
            unsafe_allow_html=True
        )

    else:

        계산된몸무게 = round(
            몸무게 * 천체중력[선택한천체],
            1
        )

        결과 = f"{계산된몸무게:,.1f}kg"

        st.markdown(
            '<div class="결과제목">' + 선택한천체 + '에서의 몸무게</div>',
            unsafe_allow_html=True
        )

        st.markdown(
            '<div class="결과숫자">' + 결과 + '</div>',
            unsafe_allow_html=True
        )

        st.markdown(
            '<div class="설명2">지구에서 '
            + f"{몸무게:,.1f}"
            + 'kg인 경우<br>'
            + 선택한천체
            + '의 중력을 기준으로 계산한 값입니다.</div>',
            unsafe_allow_html=True
        )
